#!/usr/bin/env node
'use strict';

const fs = require('fs');
const path = require('path');
const { UK_PROFILE_COUNTY_GROUPS } = require('../api/_lib/uk-profile-counties');

const outPath = path.join(__dirname, '..', 'js', 'uk-profile-counties.js');

const body =
  '/**\n' +
  ' * UK counties for welcome / profile home-base picker.\n' +
  ' * Generated by scripts/sync-uk-profile-counties.js — do not edit by hand.\n' +
  ' */\n' +
  '(function (global) {\n' +
  '  var GROUPS = ' +
  JSON.stringify(UK_PROFILE_COUNTY_GROUPS, null, 2) +
  ';\n' +
  '\n' +
  '  function slugify(name) {\n' +
  '    return String(name || "")\n' +
  '      .trim()\n' +
  '      .toLowerCase()\n' +
  "      .replace(/['’]/g, '')\n" +
  "      .replace(/&/g, 'and')\n" +
  "      .replace(/[^a-z0-9]+/g, '-')\n" +
  "      .replace(/^-+|-+$/g, '');\n" +
  '  }\n' +
  '\n' +
  '  var BY_SLUG = {};\n' +
  '  GROUPS.forEach(function (group) {\n' +
  '    (group.names || []).forEach(function (name) {\n' +
  '      var slug = slugify(name);\n' +
  '      if (!slug) return;\n' +
  '      BY_SLUG[slug] = { name: name, nation: group.nation, areaType: "county" };\n' +
  '    });\n' +
  '  });\n' +
  '\n' +
  '  global.HUB_UK_PROFILE_COUNTY_GROUPS = GROUPS;\n' +
  '  global.HUB_UK_PROFILE_COUNTIES = BY_SLUG;\n' +
  '  global.HUB_getProfileCounty = function (slug) {\n' +
  '    var key = String(slug || "").trim().toLowerCase();\n' +
  '    var row = BY_SLUG[key];\n' +
  '    return row ? { slug: key, name: row.name, nation: row.nation, areaType: row.areaType } : null;\n' +
  '  };\n' +
  '})(typeof window !== "undefined" ? window : globalThis);\n';

fs.writeFileSync(outPath, body, 'utf8');
console.log('Wrote ' + outPath);
